{
  "title": "The Mirror Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined royal city.",
      "visual_description": "A vast ruined city under a grey sky, broken towers and collapsed walls, with old royal banners hanging torn from spires. The glass diver stands at the edge, helmet reflecting the shattered skyline.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfolds her map of the city.",
      "visual_description": "Mara kneels on a rubble pile, unrolling a large ink-stained map marked with red crosses and winding paths. She points forward with a compass in hand.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "Inside a half-collapsed archway, the oracle lamp flickers on a stone ledge, its single flame-eye glowing bright. A shadowy tower looms in the background through a gap in the wall.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts the castle gates.",
      "visual_description": "The small metal fox creeps up to the massive iron castle gates, its key-wind tail ticking softly. The gates are rusted but intact, barred with a heavy chain.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector dozes at a checkpoint.",
      "visual_description": "A rickety wooden booth blocks a narrow street, the sleeping tax collector slumped over a ledger book pillow, stamped papers stuck to his sleeves. He snores lightly.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a window into a locked chamber.",
      "visual_description": "The glass diver presses a hand against a grimy window pane, which ripples like water. He steps through into a dark room filled with overturned furniture.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara finds a hidden passage on her map.",
      "visual_description": "Mara traces a faint line on her map with a fingertip, looking up at a seemingly blank wall. A secret door is suggested by a hairline crack in the stone.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp reveals the truth behind rumors of dragons.",
      "visual_description": "In a dusty courtyard, the oracle lamp casts a beam of light onto a pile of old bones and a torn banner painted with a winged shape. The flame-eye narrows, showing the 'dragon' was a hoax.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox disables a trap near a magic door.",
      "visual_description": "The tin fox carefully pulls a hidden tripwire with its teeth, deactivating a falling net. Ahead, a glowing magic door pulses with strange runes.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector is nudged awake for a key.",
      "visual_description": "Mara shakes the sleeping tax collector gently, who mumbles and points to a key hanging from his belt without opening his eyes, before dozing off again.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver opens the magic door with the key.",
      "visual_description": "The glass diver inserts the key into the magic door; the runes flare and the door swings open, revealing a dark stairwell descending.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara leads the group through a hidden tunnel.",
      "visual_description": "Mara, holding a lantern, leads the glass diver, tin fox, and oracle lamp through a narrow tunnel lined with cobwebs and old roots. The lamp casts dancing shadows.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp warns of an armored patrol.",
      "visual_description": "The oracle lamp's flame-eye widens in alarm as it senses movement above. Through a grate, the silhouette of an armored patrol passes, their metal boots echoing.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver creates a mirror distraction.",
      "visual_description": "The glass diver taps his helmet, and a beam of light reflects off it, creating a shimmering illusion of movement in a distant alley, drawing the patrol away.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector is left behind as they escape.",
      "visual_description": "The group reaches a final door, but the sleeping tax collector is still dozing back in the booth, his form small in the distance. The others turn and flee.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the escape bridge, but it is partially collapsed.",
      "visual_description": "A long stone bridge spans a chasm, but its middle section has crumbled, leaving a gap of several meters. Old royal banners hang from the far side.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver bridges the gap with a mirror path.",
      "visual_description": "The glass diver removes his helmet and holds it up, creating a solid bridge of mirrored light across the gap. The others step onto it cautiously.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The rescue team escapes the ruined city.",
      "visual_description": "All four cross the bridge and reach the far side, looking back at the ruined city as the mirrored light fades. The sunset glows behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

